"""Writes the C# SDK's generated files: dotnet/src/Rockware.Sdk/Generated/*.g.cs,
and the conformance tests' call table in dotnet/tests/Rockware.Sdk.Tests/."""

from __future__ import annotations

from .model import ROOT, Model, OperationModel, Ref, load

OUT = ROOT / "dotnet" / "src" / "Rockware.Sdk" / "Generated"
TESTS = ROOT / "dotnet" / "tests" / "Rockware.Sdk.Tests"
HEADER = (
    "// <auto-generated>\n"
    "// Made by codegen (python -m codegen dotnet) from the repo's schema/, operations/ and behavior.json.\n"
    "// Don't edit it.\n"
    "// </auto-generated>\n#nullable enable\n// Not every field has a description in the schema.\n#pragma warning disable CS1591\n\n"
)

SCALARS = {
    "ID": "string",
    "String": "string",
    "Int": "int",
    "Float": "double",
    "Boolean": "bool",
    "DateTime": "DateTimeOffset",
    "Decimal": "decimal",
    "JSON": "JsonElement",
}
VALUE_TYPES = {"int", "double", "bool", "DateTimeOffset", "decimal", "JsonElement"}
CSHARP_KEYWORDS = {
    "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked", "class", "const",
    "continue", "decimal", "default", "delegate", "do", "double", "else", "enum", "event", "explicit", "extern",
    "false", "finally", "fixed", "float", "for", "foreach", "goto", "if", "implicit", "in", "int", "interface",
    "internal", "is", "lock", "long", "namespace", "new", "null", "object", "operator", "out", "override",
    "params", "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed", "short",
    "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true", "try", "typeof",
    "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual", "void", "volatile", "while",
}  # fmt: skip


def pascal(name: str) -> str:
    return name[0].upper() + name[1:]


def param(name: str) -> str:
    return "@" + name if name in CSHARP_KEYWORDS else name


def enum_member(value: str) -> str:
    return "".join(part.capitalize() for part in value.lower().split("_"))


def cs_type(ref: Ref) -> str:
    """The C# type for a use of a type. Enums are strings, so a value the
    server adds later still reads."""
    if ref.kind == "list":
        assert ref.of
        inner = f"List<{cs_type(ref.of)}>"
    elif ref.kind == "scalar":
        inner = SCALARS[ref.name]
    elif ref.kind == "enum":
        inner = "string"
    else:
        inner = ref.name
    return inner + "?" if ref.nullable else inner


def doc(text: str | None, indent: str) -> str:
    if not text:
        return ""
    escaped = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    lines = "".join(f"{indent}/// {line}".rstrip() + "\n" for line in escaped.splitlines())
    return f"{indent}/// <summary>\n{lines}{indent}/// </summary>\n"


def verbatim(text: str) -> str:
    return '@"' + text.replace('"', '""') + '"'


def member_name(owner: str, field: str) -> str:
    name = pascal(field)
    return name + "Value" if name == owner else name


def emit_types(model: Model) -> str:
    out = [HEADER, "using System;\nusing System.Collections.Generic;\nusing System.Text.Json;\nusing System.Text.Json.Serialization;\n\n"]
    out.append("namespace Rockware;\n\n")
    for enum in model.enums:
        out.append(doc(enum.description or f"The values of {enum.name}. It's a string, so a value the server adds later still reads.", ""))
        out.append(f"public static class {enum.name}\n{{\n")
        for value in enum.values:
            out.append(f'    public const string {enum_member(value)} = "{value}";\n')
        out.append("}\n\n")
    for input_class in model.inputs:
        out.append(doc(input_class.description or f"{input_class.name}, sent to the API.", ""))
        out.append(
            "/// <remarks>Only the properties you set are sent. Setting one to null sends null, which clears that field.</remarks>\n"
        )
        out.append(f"public sealed class {input_class.name} : InputObject\n{{\n")
        for f in input_class.fields:
            name = member_name(input_class.name, f.name)
            typ = cs_type(f.ref)
            out.append(doc(f.description, "    "))
            required = "required " if not f.ref.nullable else ""
            out.append(
                f'    [JsonPropertyName("{f.name}")]\n'
                f'    public {required}{typ} {name} {{ get => Get<{typ}>("{f.name}"); set => Set("{f.name}", value); }}\n\n'
            )
        out[-1] = out[-1].rstrip("\n") + "\n"
        out.append("}\n\n")
    for object_class in model.classes:
        base = f" : {object_class.base}" if object_class.base else ""
        out.append(f"public class {object_class.name}{base}\n{{\n")
        for f in object_class.fields:
            name = member_name(object_class.name, f.name)
            typ = cs_type(f.ref)
            init = " = default!;" if not f.ref.nullable and typ not in VALUE_TYPES else ""
            out.append(doc(f.description, "    "))
            out.append(f'    [JsonPropertyName("{f.name}")]\n    public {typ} {name} {{ get; set; }}{init}\n\n')
        out[-1] = out[-1].rstrip("\n") + "\n"
        out.append("}\n\n")
    return "".join(out).rstrip("\n") + "\n"


def signature_params(op: OperationModel, variables, page: bool = False) -> list[str]:
    required = [v for v in variables if not v.ref.nullable]
    optional = [v for v in variables if v.ref.nullable]
    params = [f"{cs_type(v.ref)} {param(v.name)}" for v in required]
    params += [f"{cs_type(v.ref)} {param(v.name)} = null" for v in optional]
    if page:
        params.append("int maxPages = DefaultMaxPages")
    params.append("CancellationToken cancellationToken = default")
    return params


def variables_dict(variables) -> str:
    if not variables:
        return "new Dictionary<string, object?>()"
    items = ", ".join(f'["{v.name}"] = {param(v.name)}' for v in variables)
    return f"new Dictionary<string, object?> {{ {items} }}"


def result_type(op: OperationModel) -> str:
    return cs_type(op.result)


def emit_operations(model: Model) -> str:
    out = [HEADER, "using System;\nusing System.Collections.Generic;\n"]
    out.append("using System.Text.Json;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace Rockware;\n\n")
    out.append("/// <summary>Every operation in operations/, by name.</summary>\npublic static class Operations\n{\n")
    for op in model.operations:
        out.append(
            f'    public static readonly Operation {op.name} = new("{op.name}", "{op.root}", '
            f"{str(op.mutation).lower()}, {str(op.safe_to_repeat).lower()}, {verbatim(op.document)});\n\n"
        )
    out.append("    public static readonly IReadOnlyDictionary<string, Operation> All = new Dictionary<string, Operation>\n    {\n")
    out.append("".join(f'        ["{op.name}"] = {op.name},\n' for op in model.operations))
    out.append("    };\n}\n\n")
    out.append("internal static class Behavior\n{\n")
    out.append(f'    public const int Attempts = {model.retry["attempts"]};\n')
    out.append(f'    public const int BaseDelayMs = {model.retry["baseDelayMs"]};\n')
    out.append(f'    public const int MaxJitterMs = {model.retry["maxJitterMs"]};\n')
    out.append(f'    public const int MaxRetryAfterSeconds = {model.retry["maxRetryAfterSeconds"]};\n')
    out.append(f'    public const string Version = "{model.version}";\n}}\n\n')

    out.append("public sealed partial class RockwareClient\n{\n")
    for op in model.operations:
        typ = result_type(op)
        out.append(doc(op.description or f"Sends {op.name}.", "    "))
        out.append(
            f"    public Task<{typ}> {op.name}Async({', '.join(signature_params(op, op.variables))}) =>\n"
            f"        RunAsync<{typ}>(Operations.{op.name}, {variables_dict(op.variables)}, cancellationToken);\n\n"
        )
        if op.page_node:
            node = cs_type(op.page_node)
            page_vars = [v for v in op.variables if v.name != "after"]
            all_name = "ListAll" + op.name.removeprefix("List") + "Async"
            out.append(f"    /// <summary>Every record from {op.name}Async, page by page. See SPEC.md, Paging.</summary>\n")
            out.append(
                f"    public IAsyncEnumerable<{node}> {all_name}({', '.join(signature_params(op, page_vars, page=True))}) =>\n"
                f"        PagesAsync<{node}>(Operations.{op.name}, {variables_dict(page_vars)}, maxPages, cancellationToken);\n\n"
            )
    out[-1] = out[-1].rstrip("\n") + "\n"
    out.append("}\n")
    return "".join(out)


def emit_dispatch(model: Model) -> str:
    """The conformance tests' table: each operation's real method, called with
    arguments read from JSON."""
    out = [HEADER, "using System;\nusing System.Collections.Generic;\nusing System.Text.Json;\nusing System.Threading.Tasks;\n"]
    out.append("\nnamespace Rockware.Tests;\n\ninternal static class Dispatch\n{\n")
    out.append("    private static T? Arg<T>(JsonElement vars, string name) =>\n")
    out.append("        vars.ValueKind == JsonValueKind.Object && vars.TryGetProperty(name, out var value)\n")
    out.append("            ? JsonSerializer.Deserialize<T>(value.GetRawText(), RockwareClient.JsonOptions)\n")
    out.append("            : default;\n\n")
    out.append("    public static readonly Dictionary<string, Func<RockwareClient, JsonElement, Task<object?>>> Calls = new()\n    {\n")
    for op in model.operations:
        args = ", ".join(f'{param(v.name)}: Arg<{cs_type(v.ref)}>(vars, "{v.name}")' + ("!" if not v.ref.nullable else "") for v in op.variables)
        out.append(f'        ["{op.name}"] = async (client, vars) => await client.{op.name}Async({args}),\n')
    out.append("    };\n\n")
    out.append("    public static readonly Dictionary<string, Func<RockwareClient, JsonElement, int, IAsyncEnumerable<object>>> Pages = new()\n    {\n")
    for op in model.operations:
        if not op.page_node:
            continue
        page_vars = [v for v in op.variables if v.name != "after"]
        args = [f'{param(v.name)}: Arg<{cs_type(v.ref)}>(vars, "{v.name}")' + ("!" if not v.ref.nullable else "") for v in page_vars]
        args.append("maxPages: maxPages")
        all_name = "ListAll" + op.name.removeprefix("List") + "Async"
        out.append(f'        ["{op.name}"] = (client, vars, maxPages) => Box(client.{all_name}({", ".join(args)})),\n')
    out.append("    };\n\n")
    out.append("    private static async IAsyncEnumerable<object> Box<T>(IAsyncEnumerable<T> items)\n    {\n")
    out.append("        await foreach (var item in items) yield return item!;\n    }\n}\n")
    return "".join(out)


def main() -> None:
    model = load()
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "Types.g.cs").write_text(emit_types(model))
    (OUT / "Operations.g.cs").write_text(emit_operations(model))
    TESTS.mkdir(parents=True, exist_ok=True)
    (TESTS / "Dispatch.g.cs").write_text(emit_dispatch(model))
    print(f"Made {len(model.operations)} operations for the C# SDK {model.version}.")

